_BOOT='hgl-local-v01-6c1a672fdfcb4d7197e38aa31a02f9b5'
BRIDGE_VERSION='0.3.2'
_LOCK=threading.RLock()
_RUNTIME=None
_STAGE='spider-loaded'
_PATH_INFO={'strategy':'python-private-paths','source':'','attempts':[]}

def _stage(name):
    global _STAGE
    _STAGE=name

def _safe_text(value,limit=1600):
    # Never print a session token, a signed URL query, or an Android private path.
    text=str(value)[:16000]
    text=re.sub(r'(https?://[^\s?\"<>]+)\?[^\s\"<>]*',r'\1?[redacted]',text)
    text=re.sub(r'(?i)((?:token|password|secret|x-hg-key|x-hg-bootstrap|spade_a|key_seed)\s*[=:\"\']+\s*)[^\s,}\"\']+',r'\1[redacted]',text)
    text=text.replace(_BOOT,'[bootstrap-redacted]')
    if _RUNTIME:
        token=str(_RUNTIME[1].get('token',''))
        if token:text=text.replace(token,'[session-redacted]')
    text=re.sub(r'/(?:data/(?:user(?:_de)?/\d+|data)/[^/\s]+|mnt/expand/[^/\s]+/user/\d+/[^/\s]+)/[^\s\"\']+', '[app-private-path]',text)
    return text[:limit]

def _error(exc):
    frames=traceback.extract_tb(exc.__traceback__)[-10:]
    return {'ok':False,'local':True,'bridgeVersion':BRIDGE_VERSION,
            'code':'LOCAL_BOOTSTRAP_ERROR','stage':_STAGE,
            'error':_safe_text(type(exc).__name__+': '+str(exc)),
            'python':sys.version.split()[0],'paths':dict(_PATH_INFO),
            # Frame locations only. Do not include source lines or local variables.
            'trace':['%s:%d in %s'%(os.path.basename(x.filename),x.lineno,x.name) for x in frames]}

def _private_app_base(value):
    """Recognize app-internal storage only; never derive a root from shared storage.

    HOME is documented by Chaquopy as the app's files directory. __file__ and
    TMPDIR are fallback anchors for hosts which replace or omit HOME. The path
    is resolved first to handle /data/data aliases and reject external symlinks.
    No package name, Android user ID, or obfuscated Java class name is assumed.
    """
    value=str(value or '')
    if not value or len(value)>8192 or not os.path.isabs(value):return None
    if '..' in Path(value).parts:return None
    try:value=os.path.realpath(value)
    except (OSError,ValueError):return None
    match=re.match(
        r'^(?P<app>/data/(?:user(?:_de)?/[0-9]+|data)/[A-Za-z0-9_.-]+'
        r'|/mnt/expand/[A-Za-z0-9_.-]+/user(?:_de)?/[0-9]+/[A-Za-z0-9_.-]+)'
        r'/(?:files|cache|code_cache)(?:/|$)',value)
    return Path(match.group('app')) if match else None


def _prepare_app_roots(base):
    """Verify ownership and write access without changing existing user files."""
    base=Path(base).resolve()
    if not base.is_dir():raise OSError('app data directory is unavailable')
    if hasattr(os,'getuid') and base.stat().st_uid!=os.getuid():
        raise PermissionError('app data directory does not belong to this process')
    roots=(base/'files'/'hongguo-local-01',base/'cache'/'hongguo-local-01')
    for folder in roots:
        # Reject unexpected links out of the selected application directory.
        try:folder.resolve().relative_to(base)
        except ValueError:raise PermissionError('private directory resolves outside app storage')
        folder.mkdir(mode=0o700,parents=True,exist_ok=True)
        try:folder.resolve().relative_to(base)
        except ValueError:raise PermissionError('private directory resolves outside app storage')
        # A real write/read probe is stronger than os.access; it also exposes
        # low-storage and read-only-filesystem failures at the correct stage.
        with tempfile.TemporaryFile(mode='w+b',prefix='.hg-path-check-',dir=str(folder)) as probe:
            probe.write(b'hg-private-path-check');probe.flush();probe.seek(0)
            if probe.read()!=b'hg-private-path-check':raise OSError('private directory probe failed')
    return roots


def _root():
    global _PATH_INFO
    _PATH_INFO={'strategy':'python-private-paths','source':'','attempts':[]}
    seen=set()
    anchors=(('HOME',os.environ.get('HOME','')),
             ('script-file',globals().get('__file__','')),
             ('TMPDIR',os.environ.get('TMPDIR','')))
    for source,value in anchors:
        base=_private_app_base(value)
        if base is None:
            _PATH_INFO['attempts'].append({'source':source,'result':'missing' if not value else 'not-app-private'})
            continue
        if str(base) in seen:continue
        seen.add(str(base))
        try:
            roots=_prepare_app_roots(base)
        except (OSError,ValueError) as exc:
            # Error kind only: never send device paths or file contents to the UI.
            _PATH_INFO['attempts'].append({'source':source,'result':type(exc).__name__,
                                          'errno':getattr(exc,'errno',None)})
            continue
        _PATH_INFO['source']=source
        _PATH_INFO['attempts'].append({'source':source,'result':'writable'})
        return roots
    # Explicit desktop harness only. No public /sdcard, /storage or /tmp
    # fallback is enabled on Android, and no storage permission is requested.
    test=os.environ.get('HG_LOCAL_TEST_ROOT','')
    if test and not hasattr(sys,'getandroidapilevel') and 'java' not in sys.modules:
        roots=_prepare_app_roots(Path(test))
        _PATH_INFO['source']='desktop-test'
        return roots
    summary='; '.join(x['source']+'='+x['result'] for x in _PATH_INFO['attempts'])
    raise RuntimeError('未取得可写的 App 私有目录（'+summary+'）；'
                       '请复制启动诊断，不要改成共享存储路径或申请所有文件权限')

def _runtime(options):
    global _RUNTIME
    with _LOCK:
        if _RUNTIME is not None:return _RUNTIME
        _stage('android-paths')
        root,cache=_root();folder=root/_SHA[:16];root.mkdir(parents=True,exist_ok=True)
        _stage('payload-check')
        raw=base64.b85decode(_DATA.encode('ascii'))
        if hashlib.sha256(raw).hexdigest()!=_SHA:raise RuntimeError('插件内容校验失败；请重新上传完整 Python 文件')
        _stage('payload-unpack')
        with zipfile.ZipFile(io.BytesIO(raw)) as z:
            infos=z.infolist()
            if sum(x.file_size for x in infos)>8*1024**2:raise RuntimeError('插件体积异常')
            folder.mkdir(parents=True,exist_ok=True)
            for item in infos:
                parts=Path(item.filename).parts
                if item.filename.startswith('/') or '..' in parts or '\\' in item.filename:raise RuntimeError('插件路径无效')
                target=folder/item.filename
                if item.is_dir():target.mkdir(parents=True,exist_ok=True);continue
                content=z.read(item)
                if target.is_symlink():raise RuntimeError('插件目录存在意外链接')
                if not target.is_file() or hashlib.sha256(target.read_bytes()).digest()!=hashlib.sha256(content).digest():
                    target.parent.mkdir(parents=True,exist_ok=True);tmp=target.with_name(target.name+'.tmp');tmp.write_bytes(content);os.replace(tmp,target)
        if str(folder) not in sys.path:sys.path.insert(0,str(folder))
        _stage('crypto-import')
        # Reuse the bundled crypto backend; never install packages or download binaries.
        importlib.import_module('_hgl14_crypto')
        _stage('engine-import')
        engine=importlib.import_module('_hgl14_server')
        profile=options.get('reference')
        if isinstance(profile,dict):engine.PROFILE['reference']=dict(profile)
        _stage('device-registration')
        from _hgl14_device import DeviceRegistration
        engine._device_manager=DeviceRegistration(root/'app-device-registration.json',engine.remote,engine.protocol)
        engine.ensure_app_context=engine._device_manager.ensure
        engine.ensure_app_context()
        _stage('local-listener')
        descriptor=engine.start_local(cache,options)
        _RUNTIME=(engine,descriptor)
        _stage('ready')
        return _RUNTIME

def _response(payload,status=200):
    return [status,'application/json; charset=utf-8',json.dumps(payload,ensure_ascii=False),
            {'Cache-Control':'no-store','X-Content-Type-Options':'nosniff'}]

class Spider(BaseSpider):
    def init(self,extend=''):
        # Keep init lightweight: PyLoader caches SpiderNull after any init exception.
        # bootstrap performs runtime work and returns an explicit ok:false on failure.
        self._option_error=''
        if isinstance(extend,str):
            try:extend=json.loads(extend or '{}')
            except (ValueError,TypeError):
                extend={};self._option_error='ext 不是有效的 JSON 对象'
        if not isinstance(extend,dict):
            extend={};self._option_error='ext 必须是配置对象'
        self.options=extend
        self.engine=None;self.descriptor=None;self._last_error=None

    def _ensure(self):
        if getattr(self,'_option_error',''):
            _stage('options');raise ValueError(self._option_error)
        self.engine,self.descriptor=_runtime(getattr(self,'options',{}))
        return self.engine,self.descriptor

    def getName(self):return '红果本地'
    def getDependence(self):return []
    def homeContent(self,filter):return {'class':[],'list':[]}
    def homeVideoContent(self):return {'list':[]}
    def categoryContent(self,tid,pg,filter,extend):return {'list':[],'page':1,'pagecount':1,'limit':30,'total':0}
    def searchContent(self,key,quick,pg='1'):return {'list':[]}

    def detailContent(self,ids):
        if not ids:return {'list':[]}
        self._ensure()
        info=self.engine.series(str(ids[0]))
        route='#'.join(e['name']+'$'+info['id']+'|'+e['id'] for e in info['episodes'])
        return {'list':[{'vod_id':info['id'],'vod_name':info['name'],'vod_pic':info.get('pic',''),'vod_content':info.get('story',''),'vod_play_from':'本机处理','vod_play_url':route}]}

    def playerContent(self,flag,id,vipFlags):
        self._ensure()
        parts=str(id).split('|');sid=self.engine.identity(parts[0]);vid=self.engine.video_identity(parts[-1])
        # A direct native selection may bypass series(); preserve the exact context.
        with self.engine.LOCK:
            self.engine.SERIES_BY_VID[vid]=sid
            while len(self.engine.SERIES_BY_VID)>10000:
                self.engine.SERIES_BY_VID.pop(next(iter(self.engine.SERIES_BY_VID)))
        path=self.engine.ticket('/play/'+sid+'/'+vid+'.mp4',{'mode':'highest'})
        sources=self.engine.danmaku.source(self.engine,sid,vid)
        sources=[dict(row,url=self.descriptor['base']+row['url']) for row in sources]
        return {'parse':0,'playUrl':'','url':self.descriptor['base']+path,'header':{},'type':'video/mp4','danmaku':sources}

    def localProxy(self,param):
        p={str(k).lower():str(v) for k,v in (param or {}).items()}
        if p.get('x-hg-bootstrap')!=_BOOT:return _response({'ok':False,'error':'本机插件握手被拒绝'},403)
        action=p.get('action','')
        if action=='ping':
            return _response({'ok':True,'local':True,'bridgeVersion':BRIDGE_VERSION,
                              'stage':'spider-loaded','python':sys.version.split()[0],
                               'paths':dict(_PATH_INFO),
                              'siteKey':str(getattr(self,'siteKey','')),
                              'runtimeReady':_RUNTIME is not None})
        if action not in ('bootstrap','diagnostic'):return _response({'ok':False,'error':'未知本机操作'},404)
        with _LOCK:
            if action=='diagnostic':
                return _response(self._last_error or {'ok':True,'local':True,'stage':_STAGE,'bridgeVersion':BRIDGE_VERSION,'paths':dict(_PATH_INFO)})
            try:
                engine,descriptor=self._ensure()
                self._last_error=None
                payload=dict(descriptor)
                payload.update(ok=True,bridgeVersion=BRIDGE_VERSION,python=sys.version.split()[0],crypto=engine.CRYPTO_BACKEND,paths=dict(_PATH_INFO),repairVersion=engine.REPAIR_VERSION,playbackSources=list(engine.protocol.PLAYBACK_SOURCES))
                return _response(payload)
            except Exception as exc:
                self._last_error=_error(exc)
                # Transport succeeded, runtime failed. The page MUST check ok explicitly.
                return _response(self._last_error)

    def isVideoFormat(self,url):return False
    def manualVideoCheck(self):return False
    def liveContent(self,url):return ''
    def action(self,action):return {'local':True,'version':'0.2','bridgeVersion':BRIDGE_VERSION,'repairVersion':'5.13.0-auto-device'}
    def destroy(self):
        # Native playback outlives a WebView. The singleton loopback server exits
        # with the App process, not on a site switch. Restart App after updating.
        pass

