# Directory service compatibility identifiers below are internal protocol fields.
# Directory contract remains hg-directory-117; v4 also updates source transport above.
# Only discovery-bootstrap is intercepted. Media methods delegate unchanged.
_HG117_ORIGINAL_SPIDER = Spider
_HG117_MODULE = None
_HG117_LOCK = __import__('threading').RLock()

def _hg117_module():
    global _HG117_MODULE
    with _HG117_LOCK:
        if _HG117_MODULE is None:
            import base64 as _b, hashlib as _h, zlib as _z, types as _t
            _raw = _z.decompress(_b.b64decode(''))
            if len(_raw) > 1024*1024 or _h.sha256(_raw).hexdigest() != '889e56c3130b8931e9a4707ccd0266b9a18e6c92e9e166d56687b1460cab8f94':
                raise ValueError('目录扩展校验失败，未更改原播放模块')
            _m = _t.ModuleType('_hg_directory117')
            _m.__file__ = '<embedded-hg-directory117>'
            exec(compile(_raw, _m.__file__, 'exec'), _m.__dict__)
            _HG117_MODULE = _m
        return _HG117_MODULE

class Spider(_HG117_ORIGINAL_SPIDER):
    def localProxy(self, param):
        _p = {str(k).lower(): str(v) for k,v in (param or {}).items()}
        if _p.get('action') != 'discovery-bootstrap':
            return super().localProxy(param)
        import hmac as _h, json as _j
        def _reply(obj, code=200):
            return [code, 'application/json; charset=utf-8', _j.dumps(obj,ensure_ascii=False),
                    {'Cache-Control':'no-store','X-Content-Type-Options':'nosniff'}]
        if not _h.compare_digest(_p.get('x-hg-bootstrap',''), str(_BOOT)):
            return _reply({'ok':False,'code':'AUTH','error':'目录扩展握手被拒绝'},403)
        try:
            _engine, _descriptor = self._ensure()
            return _reply(_hg117_module().bootstrap(_engine, getattr(self,'options',{})))
        except Exception as _exc:
            return _reply({'ok':False,'code':getattr(_exc,'code','EXTENSION_BOOT'),
                          'error':str(_exc)[:200] if getattr(_exc,'code',None) else '目录扩展未启动：'+type(_exc).__name__,
                          'version':'1.25.0','local':True})
# END HG_DIRECTORY_EXTENSION_117


