class Spider(_HG_TV_BASE141):
    def init(self, extend=''):
        super().init(extend)
        self.options=dict(self.options)
        self._tv_lock = threading.RLock()
        self._tv_gates = [threading.RLock() for _ in range(32)]
        self._tv_service = None
        self._tv_pages = {}
        self._tv_search_cache = {}

    def _ensure(self):
        with self._tv_lock:
            engine,descriptor=super()._ensure()
            if engine.REPAIR_VERSION != _HG_TV_REPAIR_VERSION:
                raise engine.AppError('请强行停止影音TV后重开，以加载新的红果播放内核',409,'ENGINE_RESTART_REQUIRED')
            return engine,descriptor

    def getName(self):
        return '红果短剧·TV App目录'

    def _tv_directory(self):
        with self._tv_lock:
            if self._tv_service is None:
                engine, _ = self._ensure()
                module = _hg117_module()
                self._tv_service = module.DirectoryService(module.SignedReader(engine,self.options))
            return self._tv_service

    def homeContent(self, filter):
        # No network/crypto init here: categories remain visible offline.
        result = {'class': _HG_TV_META141['tabs']}
        if filter:
            result['filters'] = _HG_TV_META141['filters']
        return result

    def _tv_card141(self, item, label=''):
        card = self._tv_card(item)
        if card:
            card['vod_pic'] = _hg117_module().app_cover(card['vod_pic'])
            if label:
                card['vod_remarks'] = label + (' · ' + card['vod_remarks'] if card['vod_remarks'] else '')
        return card

    def _tv_note141(self, name, text, page=1):
        return {'list': [{'vod_id': 'hg-note:' + str(text)[:600], 'vod_name': name,
                          'vod_pic': '', 'vod_remarks': '栏目说明'}],
                'page': page, 'pagecount': page, 'limit': 1, 'total': 1}

    def homeVideoContent(self):
        # Theatre recommendations are a distinct feed from the discovery rank.
        from concurrent.futures import ThreadPoolExecutor
        service = self._tv_directory()
        def read(kind):
            try:
                return service.call('recommend', {'type': kind}).get('items', [])
            except Exception:
                return []
        with ThreadPoolExecutor(max_workers=2) as workers:
            pages = list(workers.map(read, ['drama', 'manju']))
        cards, seen = [], set()
        for index in range(max([len(x) for x in pages] or [0])):
            for n, values in enumerate(pages):
                if index >= len(values):
                    continue
                card = self._tv_card141(values[index], '推荐·' + ('真人剧' if n == 0 else '漫剧'))
                if card and card['vod_id'] not in seen:
                    cards.append(card);seen.add(card['vod_id'])
        return {'list': cards} if cards else self._tv_note141('推荐暂未加载，请进入分类重试', 'App 推荐服务暂未响应；分类入口仍可使用。')

    def _tv_page141(self, op, args, page):
        import time
        key = json.dumps([op, args], sort_keys=True, ensure_ascii=False, separators=(',', ':'))
        gate = self._tv_gates[int(hashlib.sha256(key.encode()).hexdigest()[:4], 16) % 32]
        with gate:
            now = time.monotonic()
            with self._tv_lock:
                for old_key, old in list(self._tv_pages.items()):
                    if now - old['last'] > 600:
                        self._tv_pages.pop(old_key, None)
                session = self._tv_pages.get(key)
                if session is None or page == 1 and now - session['first'] >= 300:
                    session = {'first': now, 'last': now, 'pages': {}}
                    self._tv_pages[key] = session
                if len(self._tv_pages) > 48:
                    self._tv_pages.pop(next(iter(self._tv_pages)))
                session['last'] = now
            pages = session['pages']
            if page in pages:
                return pages[page]
            start = max(pages, default=0) + 1
            if page < start or page - start > 3:
                raise _hg117_module().DirectoryError('分页会话已过期，请从第1页进入', 'CURSOR_EXPIRED', 409)
            service = self._tv_directory()
            for number in range(start, page + 1):
                previous = pages.get(number - 1)
                if previous and not previous['hasMore']:
                    return {'items': [], 'hasMore': False, 'cursor': '', 'source': previous.get('source', '')}
                request = dict(args)
                if previous:
                    request['cursor'] = previous['cursor']
                try:
                    result = service.call(op, request)
                except Exception as error:
                    if getattr(error, 'code', '') in ('CURSOR_EXPIRED', 'CURSOR_STALLED'):
                        with self._tv_lock:
                            self._tv_pages.pop(key, None)
                    raise
                pages[number] = result
            return pages[page]

    def categoryContent(self, tid, pg, filter, extend):
        if not re.fullmatch(r'[0-9]{1,3}', str(pg)) or not 1 <= int(pg) <= 100:
            raise ValueError('分页编号无效')
        page = int(pg);tid = str(tid)
        extend = extend if isinstance(extend, dict) else {}
        if tid == 'diagnostic':
            return self._tv_note141('红果运行检查', '版本 ' + _HG_TV_VERSION, page)
        try:
            if tid in ('drama', 'manju', 'ai'):
                module = _hg117_module()
                selected = {k: v for k, v in extend.items() if k in module.FILTER_KEYS}
                args = {'type': tid, 'filters': module.library_filters(selected)}
                op = 'category';board = ''
            elif tid in ('discover', 'latest', 'recommend', 'new'):
                op = 'latest' if tid == 'latest' else 'rank'
                kind = str(extend.get('kind') or ('drama' if op == 'latest' else 'all'))
                if kind not in (('drama', 'manju', 'ai') if op == 'latest' else ('all', 'drama', 'manju', 'ai')):
                    raise ValueError('剧目类型无效')
                board = str(extend.get('board') or 'ranklist_hot_play_sc')
                if tid == 'recommend':board = 'ranklist_hot_sc'
                if tid == 'new':board = 'ranklist_new_rank_sc'
                if board not in _hg117_module().BOARDS:
                    raise ValueError('榜单选项无效')
                args = {'type': kind}
                if op == 'rank':args['board'] = board
            else:
                raise ValueError('未知分类，请刷新站点配置')
            result = self._tv_page141(op, args, page)
            label = '最新上榜' if op == 'latest' and args['type'] in ('manju', 'ai') else ''
            cards = [card for card in (self._tv_card141(x, label) for x in result['items']) if card]
            if not cards:
                return self._tv_note141('本页暂无符合条件的作品', '可以清除筛选或切换其他榜单。', page)
            return {'list': cards, 'page': page, 'pagecount': page + int(result['hasMore']),
                    'limit': len(cards), 'total': page * len(cards) + int(result['hasMore']),
                    'source': result.get('source', ''), 'notice': result.get('notice', '')}
        except Exception as error:
            code = str(getattr(error, 'code', type(error).__name__))[:60]
            message = '分页已过期，请从第1页进入' if code == 'CURSOR_EXPIRED' else '目录暂未加载，请重试或切换分类'
            return self._tv_note141(message, '[' + code + '] ' + message, page)

    def searchContent(self, key, quick, pg='1'):
        keyword = str(key or '').strip()
        if not keyword or len(keyword) > 120:
            raise ValueError('请输入1至120字的搜索词')
        if not re.fullmatch(r'[0-9]{1,2}', str(pg)) or not 1 <= int(pg) <= 64:
            raise ValueError('搜索页码无效')
        page = int(pg)
        try:
            if re.fullmatch(r'[0-9]{15,22}', keyword):
                card = self._tv_card141(self._ensure()[0].series(keyword)) if page == 1 else None
                cards = [card] if card else []
                return {'list': cards, 'page': page, 'pagecount': page, 'limit': 10, 'total': len(cards)}
            result = self._tv_page141('search', {'type': 'all', 'query': keyword}, page)
            cards = [card for card in (self._tv_card141(x) for x in result['items']) if card]
            return {'list': cards, 'page': page, 'pagecount': page + int(result['hasMore']),
                    'limit': max(10, len(cards)), 'total': max(result.get('total',0), page*max(10,len(cards))+int(result['hasMore'])),
                    'source': result.get('source', '官方搜索')}
        except Exception as error:
            code = str(getattr(error, 'code', type(error).__name__))[:60]
            return self._tv_note141('搜索未完成，请重新搜索或稍后重试', '[' + code + '] 请求失败不代表没有这部剧。', page)

    def action(self, action):
        engine = self.engine
        return {'local': True, 'version': _HG_TV_VERSION, 'catalogueVersion': _HG_TV_VERSION,
                'repairVersion': getattr(engine, 'REPAIR_VERSION', _HG_TV_REPAIR_VERSION),
                'playbackSources': list(engine.protocol.PLAYBACK_SOURCES) if engine else [],
                'automaticDeviceContext': True, 'nativeTV': True,
                'htmlRequired': False, 'externalServiceRequired': False,
                'homepageSource': 'app-theatre-recommendation', 'librarySource': 'app-category',
                'discoveryBoards': 8, 'runtimeInitialized': self.engine is not None,
                'cacheMB': self.options.get('cache_mb', 512)}

    def isVideoFormat(self, url):
        return bool(re.match(r'^http://127\.0\.0\.1:\d+/play/', str(url)))

    @staticmethod
    def _tv_card(item):
        sid = str(item.get('id') or item.get('series_id') or '')
        if not re.fullmatch(r'[0-9]{1,22}', sid):
            return None
        name = str(item.get('name') or item.get('series_title') or '').strip()
        if not name:
            return None
        return {'vod_id': sid, 'vod_name': name[:180],
                'vod_pic': str(item.get('pic') or ''),
                'vod_remarks': str(item.get('remark') or item.get('subtitle') or '')[:100],
                'vod_content': str(item.get('story') or '')[:3000]}




    def detailContent(self, ids):
        if ids and str(ids[0]).startswith('hg-note:'):
            text = str(ids[0]).split(':', 1)[1]
            text += '\n分类和发现使用 App 目录；真人剧上新为今日上线，漫剧和 AI 剧上新为最新上榜。'
            text += '\n版本：' + _HG_TV_VERSION
            return {'list': [{'vod_id': str(ids[0]), 'vod_name': '红果栏目说明', 'vod_pic': '',
                             'vod_content': text, 'vod_play_from': '', 'vod_play_url': ''}]}
        if not ids:
            return {'list': []}
        engine, _ = self._ensure()
        info = engine.series(str(ids[0]))
        modes = [('高清优先', 'highest'), ('兼容模式', 'compatible')]
        if str(self.options.get('quality', 'highest')) == 'compatible':
            modes.reverse()
        groups = []
        for _, mode in modes:
            groups.append('#'.join(str(ep['name']).replace('$', '').replace('#', '') + '$' +
                                   info['id'] + '|' + ep['id'] + '|' + mode for ep in info['episodes']))
        return {'list': [{'vod_id': info['id'], 'vod_name': info['name'], 'vod_pic': info.get('pic', ''),
                          'vod_content': info.get('story', ''), 'vod_remarks': '全 %d 集' % len(info['episodes']),
                          'vod_play_from': '$$$'.join(name for name, _ in modes),
                          'vod_play_url': '$$$'.join(groups)}]}


    def playerContent(self, flag, id, vipFlags):
        parts = str(id or '').split('|')
        if len(parts) not in (2, 3):
            raise ValueError('选集编号无效，请从详情页重新选集')
        engine, descriptor = self._ensure()
        sid, vid = engine.identity(parts[0]), engine.video_identity(parts[1])
        mode = parts[2] if len(parts) == 3 else str(self.options.get('quality', 'highest'))
        if mode not in ('highest', 'compatible'):
            raise ValueError('画质策略无效')
        with engine.LOCK:
            engine.SERIES_BY_VID[vid] = sid
            while len(engine.SERIES_BY_VID) > 10000:
                engine.SERIES_BY_VID.pop(next(iter(engine.SERIES_BY_VID)))
        path = engine.ticket('/play/' + sid + '/' + vid + '.mp4', {'mode': mode})
        danmaku = engine.danmaku.source(engine, sid, vid) if vid.isdecimal() else []
        for source in danmaku:
            source['url'] = descriptor['base'] + source['url']
        return {'parse': 0, 'jx': 0, 'playUrl': '', 'url': descriptor['base'] + path,
                'header': {}, 'type': 'video/mp4', 'format': 'video/mp4', 'danmaku': danmaku}

